-- Title: Office Autorun Keys Modification
-- ID: baecf8fb-edbf-429f-9ade-31fc3f22b970
-- Status: test
-- Level: medium
-- Author: Victor Sergeev, Daniil Yugoslavskiy, Gleb Sukhodolskiy, Timur Zinniatullin, oscd.community, Tim Shelton, frack113 (split)
-- Date: 2019-10-25
-- Tags: attack.privilege-escalation, attack.persistence, attack.t1547.001
-- Description: Detects modification of autostart extensibility point (ASEP) in registry. Adversaries may modify these keys to execute malicious code when Office files are opened.
-- There are various legitimate add-ins that also use these keys and this filter list might not be exhaustive.
-- Thus, it is recommended to review and tune filters for your environment to reduce false positives before deploying to production.
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM security_logs WHERE ((((TargetObject ILIKE '%\\Word\\Addins%' OR TargetObject ILIKE '%\\PowerPoint\\Addins%' OR TargetObject ILIKE '%\\Outlook\\Addins%' OR TargetObject ILIKE '%\\Onenote\\Addins%' OR TargetObject ILIKE '%\\Excel\\Addins%' OR TargetObject ILIKE '%\\Access\\Addins%' OR TargetObject ILIKE '%test\\Special\\Perf%')) AND ((TargetObject ILIKE '%\\Software\\Wow6432Node\\Microsoft\\Office%' OR TargetObject ILIKE '%\\Software\\Microsoft\\Office%'))) AND NOT (((Details = '(Empty)') OR ((Image ILIKE 'C:\\Program Files\\Microsoft Office\\%' OR Image ILIKE 'C:\\Program Files (x86)\\Microsoft Office\\%' OR Image ILIKE 'C:\\PROGRA~2\\MICROS~2\\Office%' OR Image ILIKE 'C:\\Windows\\System32\\msiexec.exe%' OR Image ILIKE 'C:\\Windows\\SysWOW64\\msiexec.exe%' OR Image ILIKE 'C:\\Windows\\System32\\regsvr32.exe%' OR Image ILIKE 'C:\\Windows\\SysWOW64\\regsvr32.exe%') AND (TargetObject ILIKE '%\\Excel\\Addins\\AdHocReportingExcelClientLib.AdHocReportingExcelClientAddIn.1\\%' OR TargetObject ILIKE '%\\Excel\\Addins\\ExcelPlugInShell.PowerMapConnect\\%' OR TargetObject ILIKE '%\\Excel\\Addins\\NativeShim\\%' OR TargetObject ILIKE '%\\Excel\\Addins\\NativeShim.InquireConnector.1\\%' OR TargetObject ILIKE '%\\Excel\\Addins\\PowerPivotExcelClientAddIn.NativeEntry.1\\%' OR TargetObject ILIKE '%\\Outlook\\AddIns\\AccessAddin.DC\\%' OR TargetObject ILIKE '%\\Outlook\\AddIns\\ColleagueImport.ColleagueImportAddin\\%' OR TargetObject ILIKE '%\\Outlook\\AddIns\\EvernoteCC.EvernoteContactConnector\\%' OR TargetObject ILIKE '%\\Outlook\\AddIns\\EvernoteOLRD.Connect\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\OneNote.OutlookAddin%' OR TargetObject ILIKE '%\\Outlook\\Addins\\DriveFSExtensionLib.Connect\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\GoogleAppsSync.Connect\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\Microsoft.VbaAddinForOutlook.1\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\OcOffice.OcForms\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\OscAddin.Connect\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\OutlookChangeNotifier.Connect\\%' OR TargetObject ILIKE '%\\Outlook\\Addins\\UCAddin.LyncAddin.1%' OR TargetObject ILIKE '%\\Outlook\\Addins\\UCAddin.UCAddin.1%' OR TargetObject ILIKE '%\\Outlook\\Addins\\UmOutlookAddin.FormRegionAddin\\%' OR TargetObject ILIKE '%AddinTakeNotesService\\FriendlyName%')) OR (Details IS NULL) OR ((Image ILIKE 'C:\\Program Files\\Common Files\\Microsoft Shared\\ClickToRun\\%' OR Image ILIKE 'C:\\Program Files\\Common Files\\Microsoft Shared\\ClickToRun\\Updates\\%') AND Image ILIKE '%\\OfficeClickToRun.exe') OR ((Image ILIKE 'C:\\Program Files\\Common Files\\Microsoft Shared\\VSTO\\%' OR Image ILIKE 'C:\\Program Files (x86)\\Microsoft Shared\\VSTO\\%') AND Image ILIKE '%\\VSTOInstaller.exe'))) AND NOT ((((Image = 'C:\\Program Files\\Avast Software\\Avast\\RegSvr.exe' OR Image = 'C:\\Program Files\\Avast Software\\Avast\\x86\\RegSvr.exe') AND TargetObject ILIKE '%\\Microsoft\\Office\\Outlook\\Addins\\Avast.AsOutExt\\%') OR ((Image = 'C:\\Program Files\\AVG\\Antivirus\\RegSvr.exe' OR Image = 'C:\\Program Files\\AVG\\Antivirus\\x86\\RegSvr.exe') AND TargetObject ILIKE '%\\Microsoft\\Office\\Outlook\\Addins\\Antivirus.AsOutExt\\%'))))
